        "id": 7778,
        "title": "1954 &#8211; US Supreme Court makes landmark human rights decision &#8211; segregation in public schools unconstitutional",
        "text": "",
        "fullText": "In a landmark human rights decision, the United States' Supreme Court rules on Brown v. Board of Education, stating that segregation in public schools is unconstitutional\n\nThe First Indo-China war ends when France gives up North Vietnam to the Communists\n\nLocation: USA",
