        "title": "1955 &#8211; Abdul Latif Jameel appointed Toyota distributor for Saudi Arabia",
        "text": "As Toyota Motor looks to expand its operations in the Middle East, Abdul Latif Jameel is appointed Toyota distributor for Saudi Arabia.",
