        "title": "1964 &#8211; Dr. Martin Luther King, Jr. receives the Nobel Peace Prize",
        "text": "African American civil rights leader Dr.\u00a0Martin Luther King, Jr., is awarded the\u00a0Nobel Peace Prize for his non-violent resistance to racial prejudice in America. At 35 years of age, the Georgia-born minister was the youngest person ever to receive the award.",
        "fullText": "The British and French Governments announce commitment to build a tunnel under the English Channel\n\nThe first Ford Mustang from Ford Motor Company is made\n\nThe Civil Rights Act of 1964 is signed into law by President Johnson\n\nLocation: USA",
