        "title": "2005 &#8211; Abdul Latif Jameel Poverty Action Lab (J-PAL) established",
        "text": "Partnership with MIT's Poverty Action Lab begins - renamed Abdul Latif Jameel Poverty Action Lab (J-PAL).",
        "fullText": "Partnership with MIT's Poverty Action Lab begins - renamed Abdul Latif Jameel Poverty Action Lab (J-PAL). The global research center continues conducting randomized impact evaluations to answer critical questions in the fight against poverty, with the support of Community Jameel.\n\nLocation: USA",
