        "fullText": "Abdul Latif Jameel signs MoU for potential JV projects with renowned UAE develop EMAAR properties of UAE\n\nJameel Motors' Chengdu dealership won 2014 Golden Dealer Award in ALJ-FTMS comprehensive evaluation\n\nALJ Finansman Turkey wins the Capital Finance 'Best Consumer Finance Service Provider Award'\n\nALJ Finansman Turkey wins 'Finance Company of the Year' Eurasia Award\n\nToyota Turkey wins Bronze Effie Award\n\nLocation: Spain",
